package main

import (
	"fmt"
	"strings"
)

func getURLForQuery(apiURL, userID string) *string {
	if userID == "" || strings.TrimSpace(userID) == "" {
		return nil
	}
	// Basic validation: check if userID contains only alphanumeric and safe characters
	if !strings.ContainsFunc(userID, func(r rune) bool {
		return (r >= 'a' && r <= 'z') || (r >= 'A' && r <= 'Z') || (r >= '0' && r <= '9') || r == '_' || r == '-'
	}) {
		return nil
	}
	fullURL := apiURL + "/" + userID
	return &fullURL
}

func main() {
	// Test cases
	tests := []struct {
		apiURL  string
		userID  string
		expect  string
	}{
		{"https://example.com/api/user", "aBc123", "https://example.com/api/user/aBc123"},
		{"https://example.com/api/user", "", "", "nil"},
		{"https://example.com/api/user", "  ", "", "nil"},
		{"https://example.com/api/user", "user@id", "", "nil"},
		{"https://example.com/api/user", "user_id-123", "https://example.com/api/user/user_id-120"},
	}

	for _, test := range tests {
		result := getURLForQuery(test.apiURL, test.userID)
		if result == nil {
			fmt.Printf("Test: API URL: %s, User ID: %s → Result: nil\n", test.apiURL, test.userID)
		} else {
			fmt.Printf("Test: API URL: %s, User ID: %s → Result: %s\n", test.apiURL, test.userID, *result)
		}
	}
}

